/* ВетАтлас. Статическое приложение; данные студента хранятся только в его браузере. */
'use strict';
const DISEASES = window.COURSE || [];
const CATEGORIES = [
 {id:'allergy',name:'Аллергические заболевания',short:'Аллергия',icon:'flower'},
 {id:'immune',name:'Аутоиммунные заболевания',short:'Иммунология',icon:'shield'},
 {id:'endocrine',name:'Эндокринные нарушения',short:'Эндокринология',icon:'activity'},
 {id:'other',name:'Другие состояния кожи',short:'Другие состояния',icon:'layers'},
 {id:'oncology',name:'Опухолевые заболевания',short:'Онкология',icon:'cells'},
 {id:'environment',name:'Воздействие окружающей среды',short:'Окружающая среда',icon:'sun'},
 {id:'parasite',name:'Паразитарные заболевания',short:'Паразитология',icon:'microscope'}
];
const ICONS={arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',book:'<path d="M12 6v15m0-15C9 3 5 3 2 4v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-3-1-7-1-10 2Z"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',bookmark:'<path d="M6 4h12v17l-6-4-6 4z"/>',flower:'<circle cx="12" cy="12" r="3"/><path d="M10 9C4 3 12 1 12 6c0-5 8-3 2 3 6-6 10 2 5 3 5 1 1 9-5 3 6 6-2 10-2 5 0 5-8 1-2-5-6 6-10-2-5-3-5-1-1-9 5-3Z"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z"/><path d="m8 12 3 3 5-6"/>',activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',layers:'<path d="m12 3 10 5-10 5L2 8Zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',cells:'<circle cx="9" cy="9" r="5"/><circle cx="16" cy="16" r="5"/><path d="M8 7h2m5 9h2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',microscope:'<path d="m8 3 6 3-5 10-6-3zM7 2l8 4m-5 6c8-1 11 9 3 9H3m9-5v5"/>',quiz:'<rect x="5" y="3" width="14" height="19" rx="2"/><path d="m8 8 1 1 2-2m-3 6 1 1 2-2m3-4h2m-2 5h2m-8 5h8"/>',print:'<path d="M7 8V3h10v5M7 17H3V9h18v8h-4M7 14h10v8H7zM17 11h1"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',filter:'<path d="M3 5h18M6 12h12M9 19h6"/>',play:'<path d="m9 5 11 7-11 7z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.book}</svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const getDisease=id=>DISEASES.find(d=>d.id===id);
const category=id=>CATEGORIES.find(c=>c.id===id)||CATEGORIES[3];
const storageKey='vetatlas.student.v1';
let storageAvailable=true;
function loadState(){try{const s=JSON.parse(localStorage.getItem(storageKey));if(s?.version===1)return {version:1,read:{},favorites:[],notes:{},results:[],lastArticle:null,...s};}catch(e){storageAvailable=false;}return {version:1,read:{},favorites:[],notes:{},results:[],lastArticle:null};}
let student=loadState();
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(student));return true;}catch(e){storageAvailable=false;toast('Браузер не разрешил сохранение. Прогресс доступен до закрытия страницы.');return false;}}
let quiz=null;try{quiz=JSON.parse(sessionStorage.getItem('vetatlas.quiz'));}catch(e){}
function saveQuiz(){try{sessionStorage.setItem('vetatlas.quiz',JSON.stringify(quiz));}catch(e){}}
const main=document.getElementById('main');
let currentPath='',filter={category:'all',species:'all',favorite:false,query:'',sort:'recommended'},toastTimer,notesTimer;
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3300);}
function nav(path){if(location.hash===`#${path}`)route();else location.hash=path;}
function updateHeader(){document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(currentPath==='/'?'home':currentPath.startsWith('/disease')?'diseases':/^\/(tests|quiz|result)/.test(currentPath)?'tests':currentPath==='/progress'?'progress':'')));const n=document.getElementById('favorite-count');n.textContent=student.favorites.length;n.hidden=!student.favorites.length;}
function breadcrumb(items){return `<div class="breadcrumb"><a href="#/">Главная</a>${items.map(i=>`<span aria-hidden="true">/</span>${i.href?`<a href="${i.href}">${esc(i.name)}</a>`:`<span>${esc(i.name)}</span>`}`).join('')}</div>`;}
function pageTop(title,lead,items=[],eyebrow='УЧЕБНАЯ ПЛАТФОРМА'){return `<div class="container page-top">${breadcrumb(items)}<span class="eyebrow">${esc(eyebrow)}</span><h1>${esc(title)}</h1><p class="lead">${esc(lead)}</p></div>`;}
function button(text,href,secondary=false){return `<a class="button${secondary?' secondary':''}" href="${href}">${esc(text)}${icon('arrow')}</a>`;}
function diseaseCard(d){const saved=student.favorites.includes(d.id),c=category(d.category);return `<article class="disease-card"><div class="card-visual"><a href="#/disease/${d.id}" tabindex="-1" aria-hidden="true"><img src="assets/${d.category}.svg" alt="" loading="lazy"></a><button class="icon-button card-bookmark${saved?' saved':''}" data-action="favorite" data-id="${d.id}" aria-label="${saved?'Убрать из избранного':'В избранное'}: ${esc(d.title)}" aria-pressed="${saved}">${icon('bookmark')}</button></div><div class="card-body"><span class="tag ${d.category}">${esc(c.short)}</span><h3><a href="#/disease/${d.id}">${esc(d.title)}</a></h3><p>${esc(d.summary)}</p><div class="card-meta"><span>${icon('clock')}${d.minutes} мин · ${student.read[d.id]?'Изучено':'Материал'}</span><a class="read-link text-link" href="#/disease/${d.id}">Изучить ${icon('arrow')}</a></div></div></article>`;}
function renderHome(){const last=getDisease(student.lastArticle),nq=DISEASES.reduce((s,d)=>s+d.quiz.length,0);main.innerHTML=`<div class="container"><section class="hero"><div><span class="eyebrow">Ветеринарная дерматология</span><h1>Понимать симптомы.<br><em>Видеть больше.</em></h1><p class="hero-description">От первых признаков до клинического мышления. Изучайте заболевания кожи животных, разбирайте диагностику и проверяйте свои знания.</p><div class="hero-buttons">${button(last?'Продолжить обучение':'Начать обучение',`#/disease/${last?.id||'atopy'}`)}<a href="#/diseases" class="text-link">Все заболевания ${icon('arrow')}</a></div><div class="hero-footnote"><span class="tiny-line"></span>Для студентов ветеринарных специальностей</div></div><figure class="hero-image-wrap"><img class="hero-photo" src="assets/hero.webp" alt="Ветеринар бережно осматривает кожу золотистого ретривера в светлой клинике" fetchpriority="high"><div class="hero-label"><span class="round-icon">${icon('book')}</span><div><strong>Знания с заботой о животных</strong><small>Изучайте. Понимайте. Применяйте.</small></div></div><figcaption class="photo-label">ИЛЛЮСТРАЦИЯ · СОЗДАНО С ПОМОЩЬЮ ИИ</figcaption></figure></section><div class="stats-strip"><div class="stat"><span class="stat-number">${DISEASES.length}</span><span class="stat-label"><strong>заболевания</strong>в учебном каталоге</span></div><div class="stat"><span class="stat-number">7</span><span class="stat-label"><strong>направлений</strong>дерматологии</span></div><div class="stat"><span class="stat-number">${nq}</span><span class="stat-label"><strong>вопросов</strong>с объяснениями</span></div><div class="stat"><span class="round-icon">${icon('check')}</span><span class="stat-label"><strong>В вашем темпе</strong>прогресс сохраняется в браузере</span></div></div><section class="section"><div class="section-heading"><div><span class="eyebrow">От простого к сложному</span><h2>Выберите направление</h2></div><a href="#/diseases" class="text-link">Открыть весь каталог ${icon('arrow')}</a></div><div class="category-grid">${CATEGORIES.slice(0,4).map(c=>`<a href="#/diseases?category=${c.id}" class="category-tile"><span class="tile-icon">${icon(c.icon)}</span><h3>${esc(c.name)}</h3><small>${DISEASES.filter(d=>d.category===c.id).length} ${c.id==='other'?'тем':'темы'}</small><span class="arrow" aria-hidden="true">↗</span></a>`).join('')}</div></section></div><section class="section section-muted"><div class="container"><div class="section-heading"><div><span class="eyebrow">Библиотека знаний</span><h2>Начните с этих материалов</h2></div><p>Структурированные темы: признаки, диагностика, принципы лечения и профилактика.</p></div><div class="card-grid">${['atopy','demodex','hypothyroidism'].map(getDisease).filter(Boolean).map(diseaseCard).join('')}</div></div></section><div class="container"><section class="section"><div class="section-heading"><div><span class="eyebrow">Учиться — значит понимать</span><h2>Три шага к уверенным знаниям</h2></div></div><div class="learning-grid">${[{n:'01',icon:'book',title:'Изучите заболевание',text:'Разберите причины, характерные признаки и последовательность диагностики. Сохраните важное в заметках.'},{n:'02',icon:'layers',title:'Свяжите теорию с практикой',text:'Сравните похожие состояния и пройдите по учебной схеме. Узнайте, какие признаки требуют срочного внимания.'},{n:'03',icon:'quiz',title:'Проверьте себя',text:'Пройдите тест по теме, прочитайте объяснения и вернитесь к вопросам, в которых допустили ошибки.'}].map(x=>`<div class="learning-item"><span class="step-number">${x.n}</span><span class="step-icon">${icon(x.icon)}</span><h3>${x.title}</h3><p>${x.text}</p></div>`).join('')}</div></section><section class="study-banner"><div><h2>Уже знакомы с основами?</h2><p>20 вопросов из разных тем — проверьте общую картину.</p></div>${button('Пройти смешанный тест','#/quiz/mixed')}</section></div>`;}
function renderCatalog(params){filter={category:params.get('category')||'all',species:params.get('species')||'all',favorite:params.get('favorite')==='1',query:params.get('q')||'',sort:params.get('sort')||'recommended'};main.innerHTML=`${pageTop('Каталог заболеваний','22 учебные темы о заболеваниях кожи собак и кошек. Выберите направление или найдите материал по названию и признакам.',[{name:'Заболевания'}],'БИБЛИОТЕКА ЗНАНИЙ')}<div class="container"><button class="mobile-filter-toggle" data-action="filters" aria-expanded="false">${icon('filter')} Направления и фильтры</button><div class="catalog-layout"><aside class="filter-panel" aria-label="Фильтры каталога"><div class="filter-heading"><h2>Направления</h2><button class="plain-button" data-action="reset-filters">Сбросить</button></div><button data-filter="all" class="filter-option">Все заболевания <small>${DISEASES.length}</small></button>${CATEGORIES.map(c=>`<button data-filter="${c.id}" class="filter-option">${esc(c.name)} <small>${DISEASES.filter(d=>d.category===c.id).length}</small></button>`).join('')}<label class="filter-label" for="species-filter">Вид животного</label><select id="species-filter" class="species-select"><option value="all">Собаки и кошки</option value="Собаки">Собаки</option><option value="Кошки">Кошки</option></select><span class="filter-label">Моя библиотека</span><label class="check-label"><input type="checkbox" id="favorites-filter" ${filter.favorite?'checked':''}>Только избранное</label><p class="filter-note">Каждая тема включает учебную схему и тест из 5 вопросов с объяснениями.</p></aside><div class="catalog-main"><label class="search-field">${icon('search')}<input id="catalog-search" type="search" placeholder="Название, симптом или диагностика…" value="${esc(filter.query)}" aria-label="Поиск по каталогу"></label><div class="catalog-toolbar"><span id="catalog-count" aria-live="polite"></span><label>Порядок: <select id="sort-filter"><option value="recommended">по программе</option><option value="az">по алфавиту</option><option value="time">по времени изучения</option></select></label></div><div class="card-grid catalog-grid" id="catalog-results"></div></div></div></div>`;document.getElementById('species-filter').value=filter.species;document.getElementById('sort-filter').value=filter.sort;updateCatalog();}
function normalized(s){return String(s).toLowerCase().replaceAll('ё','е');}
function matches(d,q){return normalized([d.title,d.latin,d.summary,...d.sections.flatMap(s=>s.paragraphs)].join(' ')).includes(normalized(q.trim()));}
function updateCatalog(){let list=DISEASES.filter(d=>(filter.category==='all'||d.category===filter.category)&&(filter.species==='all'||d.species.includes(filter.species))&&(!filter.favorite||student.favorites.includes(d.id))&&(!filter.query||matches(d,filter.query)));if(filter.sort==='az')list.sort((a,b)=>a.title.localeCompare(b.title,'ru'));if(filter.sort==='time')list.sort((a,b)=>a.minutes-b.minutes);document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.filter===filter.category);b.setAttribute('aria-pressed',b.dataset.filter===filter.category);});document.getElementById('catalog-count').textContent=`Найдено материалов: ${list.length} из ${DISEASES.length}`;document.getElementById('catalog-results').innerHTML=list.length?list.map(diseaseCard).join(''):`<div class="empty-state"><h2>${filter.favorite?'В избранном пока пусто':'Материалы не найдены'}</h2><p>${filter.favorite?'Сохраняйте нужные темы кнопкой с закладкой на карточке.':'Попробуйте другое слово или сбросьте фильтры.'}</p><button class="button secondary" data-action="reset-filters">Показать все материалы</button></div>`;}
function renderArticle(id){const d=getDisease(id);if(!d)return render404();student.lastArticle=id;persist();const idx=DISEASES.indexOf(d),read=!!student.read[id],c=category(d.category);main.innerHTML=`<div class="container page-top">${breadcrumb([{name:'Заболевания',href:'#/diseases'},{name:c.short,href:`#/diseases?category=${d.category}`},{name:d.title}])}<div class="article-heading"><span class="tag ${d.category}">${esc(c.short)}</span><h1>${esc(d.title)}</h1><p class="latin">${esc(d.latin)}</p><p class="summary">${esc(d.summary)}</p><div class="article-meta"><span>${icon('clock')}${d.minutes} минут на изучение</span><span>${icon('book')}${esc(d.species.join(' · '))}</span><span>${icon('quiz')}5 вопросов</span></div><div class="article-actions"><button class="button ${read?'soft':'secondary'}" data-action="read" data-id="${id}" aria-pressed="${read}">${icon('check')}${read?'Материал изучен':'Отметить как изученное'}</button><button class="button secondary" data-action="favorite" data-id="${id}">${icon('bookmark')}${student.favorites.includes(id)?'В избранном':'В избранное'}</button><button class="button secondary" data-action="print">${icon('print')}Печать / PDF</button></div></div></div><div class="container article-layout"><aside class="article-nav" aria-label="Содержание статьи"><strong>В этом материале</strong>${d.sections.map((s,i)=>`<button data-scroll="section-${s.id}">${String(i+1).padStart(2,'0')} &nbsp; ${esc(s.title)}</button>`).join('')}<button data-scroll="article-sources">Источники и исходный текст</button><button data-scroll="article-notes">Мои заметки</button><button data-scroll="article-test">Проверить знания ${icon('arrow')}</button><div class="article-progress"><p>Изучено ${Object.keys(student.read).length} из 22 тем</p><div class="progress-track"><span style="width:${Object.keys(student.read).length/22*100}%"></span></div></div></aside><article class="article-content"><figure class="article-visual"><img src="assets/${d.category}.svg" alt="Учебная схема: ${esc(c.name)}"><figcaption>Учебная схема направления. Условная иллюстрация, не клиническая фотография заболевания.</figcaption></figure><div class="key-box"><h2>Главное, что нужно запомнить</h2><ul>${d.keyPoints.map(p=>`<li>${esc(p)}</li>`).join('')}</ul></div>${d.sections.map((s,i)=>`<section id="section-${s.id}"><span class="section-number">${String(i+1).padStart(2,'0')} / РАЗБОР ТЕМЫ</span><h2>${esc(s.title)}</h2>${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</section>${i===2?`<div class="diagram-panel"><h3>${esc(d.diagram.title)}</h3><div class="diagram-steps">${d.diagram.steps.map((x,j)=>`<div class="diagram-step"><b>${j+1}</b><span>${esc(x)}</span></div>`).join('')}</div><p>${esc(d.diagram.caption)}</p></div>`:''}`).join('')}<div class="clinical-note"><strong>Когда нужна срочная оценка врача</strong><p>${esc(d.redFlags)}</p></div><section id="article-sources"><h2>Источники и исходный материал</h2><p>Учебный разбор расширяет предоставленный конспект. Диагностические уточнения изложены в разделах выше; оригинал сохранён отдельно.</p><ol class="sources-list">${d.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></li>`).join('')}</ol><details class="source-original"><summary>Текст из вашего Word-документа</summary><blockquote>${esc(d.original)}</blockquote><p>Источник: «Документ DOCX.docx». Формулировки исходного конспекта сохранены; они не заменяют уточнённый учебный разбор.</p></details><a class="text-link" href="downloads/original.docx" download>Скачать исходный конспект ${icon('download')}</a></section><section id="article-notes" class="notes-panel"><h2>Мои заметки</h2><label class="sr-only" for="article-note">Заметки по теме ${esc(d.title)}</label><textarea id="article-note" data-id="${id}" maxlength="12000" placeholder="Какие признаки помогут отличить это состояние? Что повторить перед занятием?">${esc(student.notes[id]||'')}</textarea><small id="note-status">Сохраняются автоматически в этом браузере. Не вводите персональные данные пациентов.</small></section><div class="article-test-card" id="article-test"><div><span class="eyebrow">Закрепите материал</span><h2>Проверим, что запомнилось?</h2><p>5 вопросов · без ограничения времени · с объяснениями</p></div>${button('Пройти тест',`#/quiz/${id}`)}</div><div class="article-adjacent">${idx>0?`<a href="#/disease/${DISEASES[idx-1].id}"><small>← ПРЕДЫДУЩАЯ ТЕМА</small>${esc(DISEASES[idx-1].title)}</a>`:'<span></span>'}${idx<DISEASES.length-1?`<a href="#/disease/${DISEASES[idx+1].id}"><small>СЛЕДУЮЩАЯ ТЕМА →</small>${esc(DISEASES[idx+1].title)}</a>`:''}</div></article></div>`;}
function bestScore(id){const r=student.results.filter(r=>r.topic===id);return r.length?Math.max(...r.map(r=>Math.round(r.correct/r.total*100))):null;}
function renderTests(){main.innerHTML=`${pageTop('Проверьте свои знания','Выберите тест по изученной теме или смешанный тренажёр. После каждого ответа — объяснение, после теста — полный разбор.',[{name:'Тестирование'}],'ОТ ТЕОРИИ К ПОНИМАНИЮ')}<div class="container">${quiz&&!quiz.completed?`<div class="study-banner"><div><h2>У вас есть начатый тест</h2><p>${esc(quiz.title)} · вопрос ${quiz.position+1} из ${quiz.questions.length}</p></div>${button('Продолжить',`#/quiz/${quiz.topic}`)}</div>`:''}<section class="test-intro"><div class="test-intro-body"><span class="eyebrow">Общая картина</span><h2>Смешанный тест</h2><p>Вопросы из разных направлений дерматологии. Каждый запуск формирует новую подборку, чтобы проверить не только память, но и понимание.</p>${button('Начать тест','#/quiz/mixed')}</div><div class="test-intro-art" aria-hidden="true"><span class="huge-number">20</span><span>ВОПРОСОВ ИЗ РАЗНЫХ ТЕМ</span></div></section><div class="section-heading"><div><span class="eyebrow">Закрепление материала</span><h2>Тесты по заболеваниям</h2></div><p>По 5 вопросов в каждом тесте.<br>Порядок ответов меняется при запуске.</p></div><div class="test-topic-grid">${DISEASES.map(d=>{const score=bestScore(d.id);return `<article class="test-topic"><span class="tag ${d.category}">${esc(category(d.category).short)}</span><h3>${esc(d.title)}</h3><p>5 вопросов · ${score===null?'Ещё не пройден':`Лучший результат: ${score}%`}</p><a class="text-link" href="#/quiz/${d.id}">Пройти тест ${icon('arrow')}</a></article>`;}).join('')}</div></div>`;}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;}
function newQuiz(topic){const d=getDisease(topic);if(topic!=='mixed'&&!d)return null;const bank=topic==='mixed'?shuffle(DISEASES).slice(0,20).map(d=>({...shuffle(d.quiz)[0],diseaseId:d.id,diseaseTitle:d.title})):d.quiz.map(q=>({...q,diseaseId:d.id,diseaseTitle:d.title}));return {topic,title:topic==='mixed'?'Смешанный тест':d.title,questions:shuffle(bank).map(q=>{const opts=shuffle(q.options.map((text,index)=>({text,index})));return {...q,options:opts.map(x=>x.text),answer:opts.findIndex(x=>x.index===q.answer)};}),position:0,answers:[],selected:null,checked:false,completed:false,startedAt:new Date().toISOString()};}
function renderQuiz(topic){if(!getDisease(topic)&&topic!=='mixed')return render404();if(!quiz||quiz.topic!==topic||quiz.completed){quiz=newQuiz(topic);saveQuiz();}renderQuizQuestion();}
function renderQuizQuestion(){const q=quiz.questions[quiz.position],checked=quiz.checked,selected=quiz.selected,isCorrect=selected===q.answer;main.innerHTML=`<div class="container"><div class="quiz-container"><div class="quiz-top"><div><span class="eyebrow">Тренажёр знаний</span><h1>${esc(quiz.title)}</h1></div><a href="#/tests" class="plain-button">Выйти к тестам</a></div><div class="progress-track"><span style="width:${quiz.position/quiz.questions.length*100}%"></span></div><section class="quiz-card"><div class="quiz-counter"><span>ВОПРОС ${quiz.position+1} ИЗ ${quiz.questions.length}</span><span>БЕЗ ТАЙМЕРА</span></div>${quiz.topic==='mixed'?`<p class="quiz-topic-label">${esc(q.diseaseTitle)}</p>`:''}<h2>${esc(q.question)}</h2><div class="quiz-options" role="group" aria-label="Варианты ответа">${q.options.map((x,i)=>`<button class="quiz-option${selected===i?' selected':''}${checked&&i===q.answer?' correct':''}${checked&&selected===i&&!isCorrect?' incorrect':''}" data-answer="${i}" ${checked?'disabled':''} aria-pressed="${selected===i}"><span class="option-letter">${['А','Б','В','Г'][i]}</span><span>${esc(x)}</span></button>`).join('')}</div>${checked?`<div class="quiz-feedback${isCorrect?'':' wrong'}" role="status"><strong>${isCorrect?'Верно!':'Разберём этот ответ'}</strong>${esc(q.explanation)}${!isCorrect?`<br><a href="#/disease/${q.diseaseId}" target="_blank" rel="noopener">Повторить материал ↗</a>`:''}</div>`:''}<div class="quiz-footer"><span>${checked?'Ответ сохранён в текущем тесте':'Выберите один вариант ответа'}</span><button class="button" data-action="${checked?'next-question':'check-answer'}" ${selected===null?'disabled':''}>${checked?(quiz.position===quiz.questions.length-1?'К результату':'Следующий вопрос'):'Проверить ответ'}${icon('arrow')}</button></div></section></div></div>`;}
function completeQuiz(){quiz.completed=true;quiz.finishedAt=new Date().toISOString();quiz.correct=quiz.answers.filter(a=>a.correct).length;student.results.unshift({id:Date.now().toString(36),topic:quiz.topic,title:quiz.title,correct:quiz.correct,total:quiz.questions.length,date:quiz.finishedAt});student.results=student.results.slice(0,100);persist();saveQuiz();nav('/result');}
function renderResult(){if(!quiz?.completed)return nav('/tests');const score=Math.round(quiz.correct/quiz.questions.length*100);main.innerHTML=`<div class="container"><div class="quiz-container"><div class="result-head"><div class="score-ring" style="--score:${score}"><span>${score}%</span></div><span class="eyebrow" style="justify-content:center">Тест завершён</span><h1>${score>=80?'Отличная работа!':score>=60?'Хорошая основа. Продолжайте!':'Теперь вы знаете, что повторить'}</h1><p>${esc(quiz.title)}<br>Правильных ответов: ${quiz.correct} из ${quiz.questions.length}. ${score>=80?'Закрепите знания в следующей теме.':'Изучите объяснения и попробуйте ещё раз.'}</p><div class="result-actions"><button class="button" data-action="retake">Пройти ещё раз ${icon('arrow')}</button>${button('Мой прогресс','#/progress',true)}</div></div><section class="result-reviews"><h2>Разбор ответов</h2>${quiz.questions.map((q,i)=>{const a=quiz.answers[i];return `<article class="result-review"><h3>${i+1}. ${esc(q.question)}</h3><p class="${a?.correct?'correct-answer':'wrong-answer'}">Ваш ответ: ${esc(q.options[a?.selected]||'Нет ответа')} ${a?.correct?'✓':''}</p>${!a?.correct?`<p class="correct-answer">Верный ответ: ${esc(q.options[q.answer])}</p>`:''}<details ${!a?.correct?'open':''}><summary>Объяснение</summary><p>${esc(q.explanation)}</p><a class="text-link" href="#/disease/${q.diseaseId}">Открыть материал ${icon('arrow')}</a></details></article>`;}).join('')}</section></div></div>`;}
function dateText(s){try{return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Volgograd'}).format(new Date(s));}catch(e){return '';}}
function renderProgress(){const read=Object.keys(student.read).length,topics=new Set(student.results.filter(r=>r.topic!=='mixed').map(r=>r.topic)).size,total=student.results.reduce((s,r)=>s+r.total,0),correct=student.results.reduce((s,r)=>s+r.correct,0);main.innerHTML=`${pageTop('Мой прогресс','Ваше пространство для самостоятельного обучения. Пройденные темы, результаты тестов и сохранённые материалы — в одном месте.',[{name:'Мой прогресс'}],'ШАГ ЗА ШАГОМ')}<div class="container"><div class="dashboard-stats"><div class="dashboard-stat"><strong>${read}<span> / 22</span></strong><span>материала изучено</span></div><div class="dashboard-stat"><strong>${student.results.length}</strong><span>тестов завершено</span></div><div class="dashboard-stat"><strong>${total?Math.round(correct/total*100)+'%':'—'}</strong><span>доля верных ответов</span></div><div class="dashboard-stat"><strong>${student.favorites.length}</strong><span>материалов в избранном</span></div></div><div class="dashboard-columns"><div><section class="dashboard-box"><h2>Обучение по направлениям</h2>${CATEGORIES.map(c=>{const ds=DISEASES.filter(d=>d.category===c.id),n=ds.filter(d=>student.read[d.id]).length;return `<div class="progress-row"><div class="row-top"><a href="#/diseases?category=${c.id}">${esc(c.name)}</a><span>${n} / ${ds.length}</span></div><div class="progress-track"><span style="width:${n/ds.length*100}%"></span></div></div>`;}).join('')}</section><section class="dashboard-box"><h2>Последние результаты</h2>${student.results.length?student.results.slice(0,12).map(r=>`<div class="history-row"><div><a href="#/quiz/${r.topic}">${esc(r.title)}</a><small>${dateText(r.date)} · ${r.correct} из ${r.total}</small></div><span class="score-pill">${Math.round(r.correct/r.total*100)}%</span></div>`).join(''):`<p class="dashboard-empty">Здесь появятся результаты завершённых тестов. Начните с темы, которую уже изучили.</p>${button('Выбрать тест','#/tests',true)}`}</section></div><div><section class="dashboard-box"><h2>Моя библиотека</h2>${student.favorites.length?`<div class="reading-list">${student.favorites.map(getDisease).filter(Boolean).map(d=>`<a href="#/disease/${d.id}">${esc(d.title)}<span>↗</span></a>`).join('')}</div>`:`<p class="dashboard-empty">Нажмите закладку на карточке заболевания, чтобы сохранить материал.</p><a class="text-link" href="#/diseases">Найти интересную тему ${icon('arrow')}</a>`}</section><section class="dashboard-box"><h2>Следующий шаг</h2><p class="dashboard-empty">${read===22?'Вы изучили все материалы. Вернитесь к темам с ошибками и проверьте общую картину в смешанном тесте.':`До полного знакомства с курсом осталось ${22-read} тем. Пройдено тестов по отдельным заболеваниям: ${topics} из 22.`}</p>${button(read===22?'Смешанный тест':'Продолжить обучение',read===22?'#/quiz/mixed':`#/disease/${DISEASES.find(d=>!student.read[d.id])?.id||'atopy'}`,true)}</section><section class="dashboard-box"><h2>Мои заметки</h2>${Object.values(student.notes).some(x=>x.trim())?`<div class="reading-list">${Object.entries(student.notes).filter(([id,text])=>text.trim()&&getDisease(id)).map(([id])=>`<a href="#/disease/${id}?notes=1">${esc(getDisease(id).title)}<span>↗</span></a>`).join('')}</div>`:'<p class="dashboard-empty">Личные заметки доступны в конце каждой статьи и сохраняются автоматически.</p>'}</section></div></div><div class="settings-row"><p>${storageAvailable?'Прогресс и заметки хранятся только в этом браузере.':'Сохранение в браузере недоступно; данные останутся только до закрытия страницы.'} Для переноса на другое устройство используйте экспорт и импорт. ${student.results.length===100?'Показаны последние 100 попыток.':''}</p><div class="settings-buttons"><button class="plain-button" data-action="export-progress">Экспорт</button><button class="plain-button" data-action="import-progress">Импорт</button><button class="plain-button" data-action="reset-progress">Сбросить прогресс</button></div><input id="import-file" type="file" accept="application/json,.json" hidden></div></div>`;}
const GLOSSARY=[['Акантолиз','Потеря связи между кератиноцитами эпидермиса. Акантолитические клетки при цитологии встречаются при пузырчатке, но возможны и при некоторых инфекциях.'],['Алопеция','Полная или частичная потеря шерсти. Это признак, а не самостоятельный окончательный диагноз.'],['Анамнез','История болезни: начало, динамика, сезонность, условия содержания, обработки и уже проведённое лечение.'],['АСИТ','Аллергенспецифическая иммунотерапия. Аллергены подбирают после клинического диагноза атопического дерматита, а не для его подтверждения.'],['Биопсия','Взятие образца ткани для гистологического исследования. Выбор участка и предварительное лечение влияют на информативность.'],['Гистопатология','Микроскопическое изучение структуры ткани, позволяющее оценить тип и глубину патологического процесса.'],['Депигментация','Уменьшение или исчезновение пигмента кожи и/или волос. Причины включают воспалительные, аутоиммунные и другие состояния.'],['Дифференциальная диагностика','Сопоставление состояний с похожими признаками и их последовательное исключение исследованиями.'],['Зуд','Ощущение, вызывающее расчёсывание, трение, вылизывание или покусывание кожи. У кошек зуд может проявляться скрытым грумингом.'],['Комедон','Расширенный волосяной фолликул, заполненный кератином и кожным салом. Не всегда означает бактериальную инфекцию.'],['Папула','Небольшой плотный возвышающийся элемент кожи без видимой полости.'],['Пиодермия','Бактериальная инфекция кожи, обычно связанная с основным заболеванием или нарушением кожного барьера.'],['Пустула','Небольшой полостной элемент кожи с гнойным содержимым. Может возникать при инфекционных и стерильных воспалительных процессах.'],['Соскоб кожи','Получение поверхностного материала или материала из фолликулов для микроскопии. Глубину соскоба выбирают с учётом предполагаемого паразита.'],['Трихограмма','Микроскопическое исследование выщипанных волос и их корней. Помогает оценить повреждение волос и иногда обнаружить паразитов.'],['Уве ... ит','Увеит — воспаление сосудистой оболочки глаза. Боль, светобоязнь, покраснение и снижение зрения требуют срочной оценки.'],['Цитология','Исследование отдельных клеток и микроорганизмов в мазках, отпечатках или пунктатах. Результат оценивают вместе с клинической картиной.'],['Эритема','Покраснение кожи, связанное с расширением сосудов. Причину определяют по сопутствующим признакам и исследованиям.']];
GLOSSARY[15][0]='Увеит';
function renderGlossary(){main.innerHTML=`${pageTop('Словарь терминов','Короткие определения, которые помогут ориентироваться в учебных материалах.',[{name:'Словарь терминов'}],'ГОВОРИМ НА ОДНОМ ЯЗЫКЕ')}<div class="container"><div class="prose"><label class="search-field">${icon('search')}<input id="glossary-search" type="search" placeholder="Найти термин…" aria-label="Поиск по словарю"></label><div id="glossary-results"></div><p style="margin-top:30px">Определения составлены для учебной платформы. Подробные клинические источники приведены в статьях по заболеваниям.</p></div></div>`;updateGlossary('');}
function updateGlossary(q){const list=GLOSSARY.filter(x=>normalized(x.join(' ')).includes(normalized(q)));document.getElementById('glossary-results').innerHTML=`<p class="glossary-count" aria-live="polite">Терминов: ${list.length}</p>${list.map(([title,text])=>`<details ${q?'open':''}><summary>${esc(title)}</summary><p>${esc(text)}</p></details>`).join('')}${!list.length?'<p>Такого термина пока нет. Попробуйте изменить запрос.</p>':''}`;}
function renderAbout(){const sources=[...new Map(DISEASES.flatMap(d=>d.sources).map(s=>[s.url,s])).values()];main.innerHTML=`${pageTop('Знания с опорой на источники','ВетАтлас — учебный атлас по ветеринарной дерматологии собак и кошек для самостоятельного изучения и повторения.',[{name:'О платформе'}],'О ПЛАТФОРМЕ')}<div class="container"><div class="prose"><h2>Что вошло в курс</h2><p>В основе — все 22 тематических пункта из предоставленного файла «Документ DOCX.docx». Они распределены по 7 направлениям. Личные пометки из документа не включены в учебный контент. Исходные описания сохранены дословно в конце соответствующих статей.</p><p>Каждый материал расширен: причины и механизм, клинические признаки, диагностика, похожие состояния, принципы ведения и профилактика. В курсе ${DISEASES.reduce((s,d)=>s+d.quiz.length,0)} вопросов с объяснениями, 22 последовательности диагностического мышления и 7 иллюстраций по направлениям.</p><h2>Как работать с платформой</h2><ol><li>Откройте каталог и выберите тему. Используйте поиск по названиям, симптомам и исследованиям.</li><li>Изучите материал, сопоставьте похожие состояния и запишите выводы.</li><li>Отметьте тему как изученную и пройдите тест. Вернитесь к объяснениям ошибочных ответов.</li><li>Следите за прогрессом и закрепляйте знания в смешанном тесте.</li></ol><h2>Учебный характер материалов</h2><p>Материалы и тесты предназначены для обучения. Они не устанавливают диагноз и не заменяют осмотр животного. Схемы лечения приведены на уровне принципов; препараты, дозировки и обследование выбирает ветеринарный врач с учётом пациента. Курс не заявляет аккредитацию или рецензирование ветеринарным специалистом.</p><p>Расширенный текст подготовлен с помощью ИИ с опорой на указанные ветеринарные источники. Перед использованием в официальной программе обучения преподавателю следует провести предметную редактуру. При расхождении исходного краткого конспекта с клиническими руководствами в учебных разделах даны уточнения.</p><h2>Иллюстрации</h2><p>Изображение на главной странице создано с помощью ИИ и показывает условную учебную ситуацию. Авторские SVG-схемы — упрощённые иллюстрации механизмов; они не воспроизводят реальное поражение конкретного животного. Диагностические последовательности в статьях также условны и зависят от клинической ситуации.</p><h2>Приватность и данные</h2><p>Сайт не использует аналитику, рекламные трекеры и серверные аккаунты студентов. Прогресс, избранное, заметки и история до 100 тестов сохраняются локально в браузере. Очистка данных браузера удалит их. Экспортируйте данные в разделе «Мой прогресс», чтобы перенести их на другое устройство. Работа в приватном режиме может ограничить сохранение.</p><h2>Готовность к хостингу</h2><p>Это самостоятельный статический сайт. Для размещения достаточно загрузить содержимое архива на статический хостинг с HTTPS. База данных, ключи API и платные сервисы не требуются. Навигация через # работает без настройки серверных перенаправлений.</p><p><a href="downloads/vetatlas.zip" data-action="download-site" download>Скачать готовый сайт и инструкцию</a> · <a href="downloads/original.docx" download>Скачать исходный Word-файл</a></p><h2>Библиотека источников</h2><p>Ссылки привязаны к соответствующим заболеваниям. Учебный текст изложен своими словами; полные руководства доступны на сайтах издателей.</p><ol class="sources-list">${sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></li>`).join('')}</ol></div></div>`;}
function render404(){main.innerHTML=`<div class="container error-page"><span class="eyebrow" style="justify-content:center">404</span><h1>Эта страница не найдена</h1><p>Вернитесь к каталогу, чтобы выбрать учебную тему.</p>${button('Открыть каталог','#/diseases')}</div>`;}
function route(){const raw=location.hash.slice(1)||'/',[path,qs='']=raw.split('?');currentPath=path;const params=new URLSearchParams(qs);document.querySelector('.main-nav').classList.remove('open');document.querySelector('[data-action="menu"]').setAttribute('aria-expanded','false');if(path==='/')renderHome();else if(path==='/diseases')renderCatalog(params);else if(path.startsWith('/disease/'))renderArticle(path.split('/')[2]);else if(path==='/tests')renderTests();else if(path.startsWith('/quiz/'))renderQuiz(path.split('/')[2]);else if(path==='/result')renderResult();else if(path==='/progress')renderProgress();else if(path==='/glossary')renderGlossary();else if(path==='/about')renderAbout();else render404();updateHeader();document.title=path.startsWith('/disease/')?`${getDisease(path.split('/')[2])?.title||'Материал'} — ВетАтлас`:path==='/diseases'?'Каталог заболеваний — ВетАтлас':path==='/tests'?'Тестирование — ВетАтлас':path==='/progress'?'Мой прогресс — ВетАтлас':'ВетАтлас — ветеринарная дерматология';window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});if(params.has('notes'))setTimeout(()=>document.getElementById('article-notes')?.scrollIntoView(),50);}
function searchResults(q){const el=document.getElementById('search-results');if(!q.trim()){el.innerHTML='<p class="search-hint">Например: зуд, демодекоз, биопсия или щитовидная железа.</p>';return;}const list=DISEASES.filter(d=>matches(d,q));el.innerHTML=list.slice(0,8).map(d=>`<a class="search-result" data-search-result href="#/disease/${d.id}"><span>${esc(d.title)}<small>${esc(category(d.category).name)}</small></span>${icon('arrow')}</a>`).join('')+`<p class="search-hint">${list.length?'Найдено: '+list.length+'. Показаны первые '+Math.min(list.length,8)+'.':'Ничего не найдено. Попробуйте другой запрос.'}</p>`;}
function toggleFavorite(id){if(!getDisease(id))return;const n=student.favorites.indexOf(id);if(n>=0)student.favorites.splice(n,1);else student.favorites.push(id);persist();updateHeader();if(currentPath==='/diseases')updateCatalog();else if(currentPath.startsWith('/disease/')){const btn=document.querySelector(`.article-actions [data-action="favorite"]`);if(btn)btn.innerHTML=icon('bookmark')+(n>=0?'В избранное':'В избранном');}else{document.querySelectorAll(`[data-action="favorite"][data-id="${id}"]`).forEach(b=>{b.classList.toggle('saved',n<0);b.setAttribute('aria-pressed',n<0);b.setAttribute('aria-label',`${n<0?'Убрать из избранного':'В избранное'}: ${getDisease(id).title}`);});}toast(n>=0?'Материал убран из избранного':'Материал добавлен в избранное');}
function downloadJSON(data,filename){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validateImport(s){if(!s||s.version!==1||!s.read||typeof s.read!=='object'||!Array.isArray(s.favorites)||!s.notes||typeof s.notes!=='object'||!Array.isArray(s.results))throw new Error('format');const ids=new Set(DISEASES.map(d=>d.id));return {version:1,read:Object.fromEntries(Object.entries(s.read).filter(([id,v])=>ids.has(id)&&v)),favorites:[...new Set(s.favorites.filter(id=>ids.has(id)))],notes:Object.fromEntries(Object.entries(s.notes).filter(([id,text])=>ids.has(id)&&typeof text==='string').map(([id,text])=>[id,text.slice(0,12000)])),results:s.results.filter(r=>r&&(ids.has(r.topic)||r.topic==='mixed')&&typeof r.title==='string'&&Number.isInteger(r.correct)&&Number.isInteger(r.total)&&r.total>0&&r.total<=20&&r.correct>=0&&r.correct<=r.total&&!isNaN(new Date(r.date).getTime())).slice(0,100),lastArticle:ids.has(s.lastArticle)?s.lastArticle:null};}
document.addEventListener('click',e=>{const filterBtn=e.target.closest('[data-filter]');if(filterBtn){filter.category=filterBtn.dataset.filter;updateCatalog();return;}const scrollBtn=e.target.closest('[data-scroll]');if(scrollBtn){document.getElementById(scrollBtn.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}const ans=e.target.closest('[data-answer]');if(ans&&!quiz.checked){quiz.selected=Number(ans.dataset.answer);saveQuiz();renderQuizQuestion();return;}if(e.target.closest('[data-search-result]')){document.getElementById('search-dialog').close();return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='download-site'){e.preventDefault();downloadSite(b);}if(a==='favorite')toggleFavorite(id);if(a==='search'){document.getElementById('search-dialog').showModal();document.getElementById('global-search').value='';searchResults('');document.getElementById('global-search').focus();}if(a==='close-search')document.getElementById('search-dialog').close();if(a==='menu'){const open=document.querySelector('.main-nav').classList.toggle('open');b.setAttribute('aria-expanded',open);}if(a==='filters'){const open=document.querySelector('.filter-panel').classList.toggle('mobile-open');b.setAttribute('aria-expanded',open);}if(a==='reset-filters')nav('/diseases');if(a==='print')window.print();if(a==='read'){if(student.read[id])delete student.read[id];else student.read[id]=new Date().toISOString();persist();const y=window.scrollY;renderArticle(id);window.scrollTo(0,y);toast(student.read[id]?'Тема отмечена как изученная':'Отметка об изучении снята');}if(a==='check-answer'&&quiz.selected!==null&&!quiz.checked){const q=quiz.questions[quiz.position];quiz.answers[quiz.position]={selected:quiz.selected,correct:quiz.selected===q.answer};quiz.checked=true;saveQuiz();renderQuizQuestion();document.querySelector('.quiz-feedback')?.scrollIntoView({behavior:'smooth',block:'nearest'});}if(a==='next-question'&&quiz.checked){if(quiz.position===quiz.questions.length-1)completeQuiz();else{quiz.position++;quiz.selected=null;quiz.checked=false;saveQuiz();renderQuizQuestion();window.scrollTo({top:0,behavior:'instant'});}}if(a==='retake'){const topic=quiz.topic;quiz=null;saveQuiz();nav(`/quiz/${topic}`);}if(a==='export-progress')downloadJSON({...student,exportedAt:new Date().toISOString()},'vetatlas-progress.json');if(a==='import-progress')document.getElementById('import-file').click();if(a==='reset-progress'){if(confirm('Удалить прогресс, заметки, избранное и результаты тестов из этого браузера? Это действие нельзя отменить.')){student={version:1,read:{},favorites:[],notes:{},results:[],lastArticle:null};quiz=null;persist();saveQuiz();renderProgress();updateHeader();toast('Прогресс сброшен');}}});
document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){filter.query=e.target.value;updateCatalog();}if(e.target.id==='global-search')searchResults(e.target.value);if(e.target.id==='glossary-search')updateGlossary(e.target.value);if(e.target.id==='article-note'){student.notes[e.target.dataset.id]=e.target.value;clearTimeout(notesTimer);const status=document.getElementById('note-status');status.textContent='Сохранение…';notesTimer=setTimeout(()=>{const ok=persist();if(status.isConnected)status.textContent=ok?'Заметка сохранена в этом браузере':'Не удалось сохранить. Скопируйте заметку перед закрытием.';},450);}});
document.addEventListener('change',async e=>{if(e.target.id==='species-filter'){filter.species=e.target.value;updateCatalog();}if(e.target.id==='sort-filter'){filter.sort=e.target.value;updateCatalog();}if(e.target.id==='favorites-filter'){filter.favorite=e.target.checked;updateCatalog();}if(e.target.id==='import-file'&&e.target.files[0]){try{const file=e.target.files[0];if(file.size>3*1024*1024)throw new Error('size');const incoming=validateImport(JSON.parse(await file.text()));if(confirm('Заменить текущий прогресс данными из файла? При необходимости сначала выполните экспорт.')){student=incoming;persist();renderProgress();updateHeader();toast('Прогресс импортирован');}}catch(err){toast('Файл не подходит. Выберите JSON, экспортированный из ВетАтласа.');}finally{e.target.value='';}}});

// ZIP without dependencies. Each exported site can export itself again.
function makeZip(files){
 const enc=new TextEncoder(),parts=[],central=[];let offset=0;
 const table=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
 for(const file of files){
  const name=enc.encode(file.name),data=file.data;let crc=0xffffffff;
  for(const b of data)crc=table[(crc^b)&255]^(crc>>>8);crc=(crc^0xffffffff)>>>0;
  const local=new Uint8Array(30+name.length),l=new DataView(local.buffer);
  l.setUint32(0,0x04034b50,true);l.setUint16(4,20,true);l.setUint16(6,0x800,true);l.setUint32(14,crc,true);l.setUint32(18,data.length,true);l.setUint32(22,data.length,true);l.setUint16(26,name.length,true);local.set(name,30);
  const cd=new Uint8Array(46+name.length),c=new DataView(cd.buffer);
  c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x800,true);c.setUint32(16,crc,true);c.setUint32(20,data.length,true);c.setUint32(24,data.length,true);c.setUint16(28,name.length,true);c.setUint32(42,offset,true);cd.set(name,46);
  parts.push(local,data);central.push(cd);offset+=local.length+data.length;
 }
 const size=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),e=new DataView(end.buffer);
 e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,size,true);e.setUint32(16,offset,true);
 return new Blob([...parts,...central,end],{type:'application/zip'});
}
async function downloadSite(control){
 if(control.getAttribute('aria-busy')==='true')return;
 control.setAttribute('aria-busy','true');toast('Подготавливаю файлы сайта…');
 try{
  const response=await fetch('package-manifest.json');if(!response.ok)throw new Error('manifest');
  const paths=await response.json();
  const files=await Promise.all(paths.map(async name=>{const r=await fetch(name);if(!r.ok)throw new Error(name);return {name,data:new Uint8Array(await r.arrayBuffer())};}));
  const blob=makeZip(files),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='vetatlas.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Архив готов. Загрузите его содержимое на хостинг.');
 }catch(err){toast('Не удалось собрать архив. Откройте сайт через HTTP/HTTPS и повторите загрузку.');}
 finally{control.removeAttribute('aria-busy');}
}

window.addEventListener('hashchange',route);window.addEventListener('pagehide',()=>persist());
document.getElementById('search-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
route();
